'fd.how_1' => 'Αντιγράψτε τα αρχεία εξαγωγής στον φάκελο εισαγωγής με FTP (ή ανεβάστε ένα μικρό) και πατήστε Έλεγχος σε κάθε αρχείο: δεν γράφεται τίποτα, παίρνετε την αναφορά αντιστοίχισης.',
