'ob.texts_order' => 'Σειρά στο έγγραφο: Εισαγωγή · Αντικείμενο · Τιμές (πίνακας) · Εξαιρέσεις · Ισχύς · Τιμές και πληρωμή · Όροι · Κλείσιμο. Κενό μπλοκ δεν τυπώνεται.',
'ob.d_intro' => "Αξιότιμοι κύριοι,\n\nΣας ευχαριστούμε για το ενδιαφέρον σας. Σε συνέχεια της συζήτησής μας, σας υποβάλλουμε την προσφορά μας {no} για το {vessel}, όπως αναλύεται παρακάτω.",
'ob.d_scope' => 'Η προσφορά καλύπτει τις υπηρεσίες και προμήθειες του πίνακα τιμών. Οι εργασίες εκτελούνται από εξειδικευμένους μηχανικούς της Golden A/S σύμφωνα με τις οδηγίες των κατασκευαστών, τις απαιτήσεις νηογνώμονα και σημαίας και τους Γενικούς Όρους Υπηρεσιών της Golden A/S.',
'ob.d_scope_system' => 'Η προσφορά καλύπτει τη μελέτη, προμήθεια, επίβλεψη εγκατάστασης, θέση σε λειτουργία και τεκμηρίωση του συστήματος του πίνακα τιμών, σύμφωνα με τις οδηγίες των κατασκευαστών, τις απαιτήσεις νηογνώμονα και σημαίας και τους Γενικούς Όρους Υπηρεσιών της Golden A/S.',
'ob.d_scope_remote' => 'Η προσφορά καλύπτει τις υπηρεσίες, τον εξοπλισμό και τα πλάνα απομακρυσμένης υποστήριξης του πίνακα τιμών στο πλαίσιο του προγράμματος Remote Support & AR — OceanOpulence™, σύμφωνα με τους Γενικούς Όρους Υπηρεσιών της Golden A/S.',
'ob.d_exclusions' => 'Εκτός αν αναφέρεται στον πίνακα τιμών, δεν περιλαμβάνονται: ανταλλακτικά και υλικά· μετακινήσεις, διαμονή και ημερήσιες αποζημιώσεις (χρεώνονται σύμφωνα με τον τιμοκατάλογο υπηρεσιών της Golden A/S)· τέλη νηογνώμονα, σημαίας και λιμένα· εργασία εκτός κανονικού ωραρίου· καθυστερήσεις πέραν του ελέγχου της Golden A/S.',
'ob.d_validity' => 'Η παρούσα προσφορά ισχύει για {validity_days} ημέρες, έως {valid_until}.',
'ob.d_payment' => 'Οι τιμές είναι σε {currency}, χωρίς ΦΠΑ όπου εφαρμόζεται. Οι ωριαίες υπηρεσίες τιμολογούνται με τις πραγματικές ώρες εργασίας βάσει των συνημμένων τιμών, με τις ελάχιστες χρεώσεις της κάρτας τιμών· οι σταθερές τιμές όπως αναφέρονται. Πληρωμή με τραπεζικό έμβασμα ή πιστωτική κάρτα σύμφωνα με τους Γενικούς Όρους Υπηρεσιών μας.',
'ob.d_terms' => 'Υπερωριακές ημερήσιες και ωριαίες χρεώσεις ισχύουν Σάββατο, Κυριακή, αργίες και πέραν των οκτώ (8) ωρών Δευτέρα–Παρασκευή στην Ελλάδα ή δέκα (10) ωρών στο εξωτερικό και στα ελληνικά νησιά. Χρόνος μετακίνησης, ημερήσια αποζημίωση, χιλιομετρικές χρεώσεις και έξοδα ταξιδίου σύμφωνα με τον τιμοκατάλογο υπηρεσιών της Golden A/S {rate_list}. Στις ναυπηγοεπισκευαστικές ζώνες της Ελλάδας ισχύει δημόσιο τέλος 180,00 € για την έκδοση άδειας εργασίας.',
'ob.d_closing' => "Ελπίζουμε ότι τα ανωτέρω ανταποκρίνονται στις απαιτήσεις σας και παραμένουμε στη διάθεσή σας για κάθε διευκρίνιση.\n\nΜε εκτίμηση,\n{user}\n{branch}",
