'et.d_s_welcome' => 'Η πρόσβασή σας στο portal της Golden A/S',
'et.d_b_welcome' => "Αγαπητή/έ {name},\n\nΟ λογαριασμός σας στο portal της Golden A/S είναι έτοιμος. Ακολουθήστε τα τρία παρακάτω βήματα.\n\n1. ΠΡΩΤΗ ΣΥΝΔΕΣΗ\n   Ανοίξτε το {url} και συνδεθείτε με το e-mail σας {email} και τον προσωρινό κωδικό που σας δίνουμε ξεχωριστά (τηλεφωνικά ή με δεύτερο μήνυμα — ποτέ σε αυτό το e-mail).\n\n2. ΑΛΛΑΓΗ ΚΩΔΙΚΟΥ\n   Μετά την πρώτη σύνδεση πατήστε το avatar σας πάνω δεξιά (Ο λογαριασμός μου) και ορίστε δικό σας κωδικό στο πεδίο Νέος κωδικός: τουλάχιστον 10 χαρακτήρες, που δεν χρησιμοποιείτε αλλού.\n\n3. ΕΝΕΡΓΟΠΟΙΗΣΗ ΕΛΕΓΧΟΥ ΔΥΟ ΠΑΡΑΓΟΝΤΩΝ (2FA)\n   Στο Ο λογαριασμός μου › Έλεγχος ταυτότητας δύο παραγόντων σαρώστε τον κωδικό QR με εφαρμογή authenticator (Microsoft Authenticator, Google Authenticator, Authy, …) και πληκτρολογήστε τον 6ψήφιο κωδικό για επιβεβαίωση. Από εκεί και πέρα κάθε σύνδεση ζητά και τον κωδικό της εφαρμογής.\n\nΠέντε λανθασμένοι κωδικοί κλειδώνουν τον λογαριασμό για 15 λεπτά· αν δεν μπορείτε να συνδεθείτε, απαντήστε σε αυτό το e-mail και θα τον ξεκλειδώσουμε ή θα επαναφέρουμε τον κωδικό.\n\n{signature}",
'au.locked' => 'Κλειδωμένος',
'au.locked_until' => 'Κλειδωμένος έως {d} μετά από πολλούς λανθασμένους κωδικούς',
'au.unlock' => 'Ξεκλείδωμα',
'au.unlocked' => 'Ο λογαριασμός ξεκλειδώθηκε — μπορεί να συνδεθεί ξανά.',
'au.welcome' => 'E-mail καλωσορίσματος',
'au.welcome_hint' => 'Ανοίγει το πρόγραμμα e-mail με τις οδηγίες πρώτης σύνδεσης για το άτομο (σύνδεση, αλλαγή κωδικού, ενεργοποίηση 2FA) — στη γλώσσα του.',
'au.welcome_lede' => 'Το ✉ E-mail καλωσορίσματος ανοίγει έτοιμο μήνυμα με τις οδηγίες πρώτης σύνδεσης (διεύθυνση, αλλαγή κωδικού, 2FA) για το άτομο. Ο προσωρινός κωδικός στέλνεται ξεχωριστά, ποτέ στο ίδιο e-mail.',
