'eng.rules' => 'Ολοκλήρωση % = (βάρος ολοκληρωμένων παραδοτέων + καταχωρισμένες ώρες σε ανοικτές εργασίες, με ανώτατο όριο) ÷ (προϋπολογισμός + εγκεκριμένες πρόσθετες). Χρήση % = καταχωρισμένες ÷ προϋπολογισμός — πάνω από 100 % το τμήμα έχει υπερβεί τον συμφωνημένο προϋπολογισμό· το γραμμοσκιασμένο μέρος της μπάρας είναι οι εγκεκριμένες πρόσθετες. Στο 90 % των επιτρεπόμενων ωρών το τμήμα γίνεται πορτοκαλί· πέρα από αυτές έχει υπερβεί το όριο και οι νέες ώρες μελέτης μπλοκάρονται μέχρι να εγκριθούν πρόσθετες ώρες ή να δηλωθεί το τμήμα ολοκληρωμένο.',
