'eng.settings' => 'Τμήματα σταδίων',
'eng.settings_lede' => 'Τα τμήματα της γραμμής διεργασίας με προϋπολογισμό ωρών — Μελέτη (Ηλεκτρολογική, Αυτοματισμός, Μηχανολογική, UI/UX, IT), Παραγωγή, Πεδίο & εγκατάσταση, HAT / SAT, Θέση σε λειτουργία — και οι ειδικότητες που τα τροφοδοτούν. Ο προϋπολογισμός ενός τμήματος είναι οι προϋπολογισμένες ώρες των ειδικοτήτων του στο Προϋπολογισμός & απολογισμός του υποέργου· οι πραγματικές του ώρες είναι οι ώρες των ίδιων ειδικοτήτων που καταχωρήθηκαν στο στάδιο αυτό. Μία πηγή — συμφωνημένη με τον πελάτη· οι εγκεκριμένες πρόσθετες ώρες εμφανίζονται πάνω από αυτήν, ποτέ δεν προστίθενται σε αυτήν.',
'eng.map_title' => 'Μητρώο ειδικότητα × τμήμα',
'eng.map_hint' => 'Επιλέξτε τα τμήματα που τροφοδοτεί κάθε ειδικότητα. Οι ειδικότητες μελέτης τροφοδοτούν ένα τμήμα μελέτης· ένας εγκαταστάτης τροφοδοτεί Πεδίο & εγκατάσταση και HAT / SAT· ένας μηχανικός service ή αυτοματισμού HAT / SAT και Θέση σε λειτουργία. Μια ειδικότητα που τροφοδοτεί περισσότερα τμήματα αποκτά ένα κελί προϋπολογισμού ανά τμήμα στο Προϋπολογισμός & απολογισμός, και το στάδιο που επιλέγεται στη γραμμή του φύλλου ωρών ορίζει πού μετρούν οι ώρες της. Οι ειδικότητες διοίκησης και πωλήσεων παραμένουν χωρίς αντιστοίχιση.',
'eng.map_none' => '— όχι μελέτη',
'eng.map_save_hint' => 'Εφαρμόζεται αμέσως σε κάθε υποέργο (προϋπολογισμοί, απολογισμοί και το στάδιο Μελέτης επανυπολογίζονται από την αντιστοίχιση).',
