'eng.sec_code' => 'Κωδικός',
'eng.sec_mapped' => 'Ειδικότητες',
'eng.sec_add' => 'Προσθήκη τμήματος',
'eng.sec_hint' => 'Τα αποσυρμένα τμήματα εξαφανίζονται από τις καρτέλες αλλά διατηρούν το ιστορικό τους. Μετονομάστε αντί να διαγράψετε.',
'eng.sec_need' => 'Απαιτούνται κωδικός (γράμματα / ψηφία, έως 12) και όνομα.',
'eng.need_r47' => 'Εκτελέστε πρώτα τα install/migrate_cp_r47_engineering.sql και install/migrate_cp_r47b_eng_sections.sql.',
'eng.no_budget_yet' => 'Δεν έχουν προϋπολογιστεί ακόμη ώρες μελέτης (αναθεώρηση προϋπολογισμού {r}). Καταχωρίστε τις ώρες των ειδικοτήτων μελέτης στον Προϋπολογισμό & απολογισμό — τα τμήματα τις διαβάζουν από εκεί.',
