'ai.settings' => 'Βοηθός (Claude)',
'ai.settings_lede' => 'Το Claude ενσωματωμένο στο portal για το προσωπικό της Golden A/S: συμπλήρωση φόρμας από επικολλημένο κείμενο ή φωτογραφία, σύνταξη ή βελτίωση κειμένου, μετάφραση πεδίου στα Αγγλικά, ερωτήσεις για την εγγραφή στην οθόνη. Ο βοηθός προτείνει — ο χρήστης εφαρμόζει. Αποστέλλονται μόνο η φόρμα στην οθόνη και ο τίτλος της σελίδας· το κλειδί της εταιρείας παραμένει στον server, κρυπτογραφημένο.',
