'hr.leave_import' => 'Εισαγωγή ιστορικού αδειών',
'hr.leave_import_hint' => 'Ανεβάστε το Excel με τα παλαιότερα αιτήματα αδειών (φύλλο «Leaves»: Email, Όνομα λατινικά, Όνομα ελληνικά, Κωδικός τύπου, Από, Έως, Ημέρες, Ώρες, Κατάσταση approved / rejected / pending, Αιτιολογία, Action). Τα πρόσωπα αντιστοιχίζονται από το e-mail του λογαριασμού portal και μετά από το ελληνικό ή λατινικό όνομα· οι τύποι από τον κωδικό τους. Γραμμές που υπάρχουν ήδη (ίδιο πρόσωπο, τύπος και ημερομηνία έναρξης), ακυρώσεις και γραμμές με skip παραλείπονται. Οι εγκεκριμένες γραμμές καταχωρούνται ως αιτήματα εγκεκριμένα από το HR και περνούν στο Planning· οι εκκρεμείς περιμένουν στα αιτήματα HR. Μην μετρήσετε δύο φορές: αν η εισαγωγή υπολοίπων έγραψε ήδη τις ληφθείσες ημέρες της ίδιας χρονιάς ως αρχικές, μηδενίστε την αρχική τιμή για τα πρόσωπα των οποίων οι άδειες εισάγονται εδώ.',
